queue_external_slot() {
    local tool="$1" name="$2" out="$3"
    local agent="$PLUGIN_ROOT/agents/reviewer-${name}.md"
    printf '{"slot":"%s","tool":"%s","output":"%s","agent":"%s"}\n' "$name" "$tool" "$out" "$agent" >> "$manifest"
    static_slot_count=$((static_slot_count + 1))
}
